head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > monthNames]<br/>팝업 달력 상단의 월 영역에 표시되는 월의 이름을 설정합니다.",
    "validation" : [
        "팝업 달력의 월 영역에 표시되는 월의 이름을 콤마(',')로 구분하여 설정합니다.",
        "pickerType 속성값과 관계없이 월에 해당하는 SelectBox 와 커스텀 UI 에 모두 적용됩니다.",
        "설정된 값이 12 개가 안될 경우 기본값인 숫자가 월의 이름으로 설정됩니다.",
        "값을 설정하지 않으면 '1월,2월,3월...' 이 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        monthNames : con_monthNames.getText(),
        pickerType : con_pickerType.getText(),
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    $c.gcm.createBasicInputCalendar(cList);
}



scwin.btn_getHeadYear_onclick = function (e) {
    let element = null;
    let pickerCells = null;
    let pickerCellList = []


    if (target1.options.pickerType == "dynamic") {
        element = document.querySelector('div[class*="w2calendar_picker_header"]');

        if(element) {
            let elementDynamic = document.querySelector('div[class*="w2calendar_picker_header_dynamic_entity"]');

            element = elementDynamic;

            if (elementDynamic) {
                pickerCells = document.querySelectorAll('div[class*="w2calendar_picker_cell"]');

                if (pickerCells) {
                    for(var i=0; i < pickerCells.length; i++) {
                        if (pickerCells[i].textContent !== "")
                            pickerCellList.push(pickerCells[i].textContent);
                    }
                }
            }
        } 
    }
    else {        
        element = document.querySelector('div[id*="target1_calendar_selectbox_month_itemTable"]');
    }    

    if(pickerCellList.length > 0)             
        wf_body_bottom.getObj("scwin").setReturnValue("월 : " + pickerCellList);
    else {    
        wf_body_bottom.getObj("scwin").setReturnValue("월 : " + element.textContent);         
    }	    
};
